export function getIndustryBySubSector(subSectorCode: string): IndustrySubSectorDefinition | undefined {
  return GLOBAL_INDUSTRY_TAXONOMY.find(item => item.subSectorCode === subSectorCode);
}

export function filterIndustriesBySector(sectorCode: string): IndustrySubSectorDefinition[] {
  return GLOBAL_INDUSTRY_TAXONOMY.filter(item => item.sectorCode === sectorCode);
}